<?php

namespace App\Support;

/**
 * Tiny dependency-free PDF writer for seeded lecture notes (PRD §15:
 * "small sample PDFs generated by the seeder"). One page, Helvetica, plain text.
 */
class SamplePdf
{
    /** @param  list<string>  $lines */
    public static function make(string $title, array $lines): string
    {
        $esc = fn (string $s) => str_replace(['\\', '(', ')'], ['\\\\', '\\(', '\\)'], preg_replace('/[^\x20-\x7E]/', '-', $s));
        $content = "BT /F1 20 Tf 60 780 Td ({$esc($title)}) Tj ET\n";
        $y = 745;
        foreach ($lines as $line) {
            foreach (explode("\n", wordwrap($line, 90, "\n", true)) as $part) {
                $content .= "BT /F1 11 Tf 60 {$y} Td ({$esc($part)}) Tj ET\n";
                $y -= 16;
            }
            $y -= 6;
            if ($y < 60) {
                break;
            }
        }

        $objects = [
            '<< /Type /Catalog /Pages 2 0 R >>',
            '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
            '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>',
            '<< /Length '.strlen($content)." >>\nstream\n{$content}endstream",
            '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
        ];

        $pdf = "%PDF-1.4\n";
        $offsets = [];
        foreach ($objects as $i => $obj) {
            $offsets[] = strlen($pdf);
            $pdf .= ($i + 1)." 0 obj\n{$obj}\nendobj\n";
        }
        $xref = strlen($pdf);
        $pdf .= 'xref
0 '.(count($objects) + 1)."\n0000000000 65535 f \n";
        foreach ($offsets as $o) {
            $pdf .= sprintf("%010d 00000 n \n", $o);
        }
        $pdf .= 'trailer << /Size '.(count($objects) + 1)." /Root 1 0 R >>\nstartxref\n{$xref}\n%%EOF\n";

        return $pdf;
    }
}
